// Single entry: the schedule. Everything a user tunes lives in the Config node.
const cfg = (() => { try { return $('⚙️ Config').first().json; } catch (e) { return {}; } })();
const chat = String(cfg.chat_id || '').trim();
if (!chat) throw new Error('Set chat_id in the Config node. Message your bot, then read the id from the Telegram trigger output.');
return [{ json: {
  source: 'scheduled',
  chat_id: chat,
  language: cfg.language || 'en',
  threshold: Number(cfg.threshold_pct) || 4,      // flag a move of this size either way
  big_threshold: Number(cfg.big_move_pct) || 7
}}];

// --- Yahoo symbol resolution -------------------------------------------------
// The sheet's `ticker` column is Fritz's own shorthand and is NOT always a valid
// Yahoo symbol. Bare European tickers silently resolve to a DIFFERENT company on
// a US exchange: 'GLE' is Global Engine Group (a $0.46 Nasdaq penny stock), not
// Societe Generale; 'ALV' is Autoliv, not Allianz; 'CBK' is Commercial Bancgroup,
// not Commerzbank; 'SGLN' is Surgline Intl, not iShares Physical Gold. Those
// return real-looking prices under the wrong name, which is worse than no data.
// An optional `yahoo` column in the sheet always wins if present.
const YAHOO = {
  'CBK':'CBK.DE', 'BAYN':'BAYN.DE', 'ALV':'ALV.DE', 'HOT':'HOT.DE',
  'GLE':'GLE.PA', 'SAN':'SAN.MC', 'ASML':'ASML.AS',
  'CSPX':'CSPX.L', 'SGLN':'SGLN.L', 'BRK.B':'BRK-B'
};
function resolveSymbol(row, ticker){
  const explicit = String(row.yahoo || row.Yahoo || '').trim();
  if (explicit) return explicit;
  return YAHOO[ticker.toUpperCase()] || ticker;
}

const ctx=$('Normalize Trigger').first().json;
const rows=$input.all().map(i=>i.json).filter(r=>r);
let holdings=rows.map(r=>{
  const ticker=String(r.ticker||r.Ticker||'').trim();
  return { ticker, yahoo: resolveSymbol(r, ticker),
    name:String(r.name||r.Name||'').trim(),
    market:String(r.market||r.Market||'US').trim() };
}).filter(h=>h.ticker && h.ticker!=='-' && h.ticker!=='—');
if(!holdings.length) holdings=[{ticker:'AAPL',yahoo:'AAPL',name:'Apple',market:'US'}];

const SIZE=20, out=[];
for(let i=0;i<holdings.length;i+=SIZE){
  const chunk=holdings.slice(i,i+SIZE);
  out.push({ json:{ ...ctx, batch_index: out.length,
    symbols: chunk.map(h=>h.yahoo).join(','),
    meta: chunk } });
}
return out;

const ctx=$('Normalize Trigger').first().json;

// USD -> EUR (European tickers already quote in EUR)
let rates={};
try {
  const fx=$('Fetch FX').first().json;
  rates=(fx && fx.rates) || {};   // EUR -> X, so X -> EUR is a DIVIDE
} catch(e){}
// Not everything non-EUR is USD: SGLN.L quotes in GBp (pence), CSPX.L in USD
// despite being London-listed. Treating pence as dollars was off by ~75x.
function toEur(price, cur){
  if(typeof price!=='number') return null;
  if(cur==='EUR') return price;
  if(cur==='GBp'||cur==='GBX') return rates.GBP ? (price/100)/rates.GBP : null;
  const r=rates[cur];
  return r ? price/r : null;
}

// name lookup from the sheet
const meta={};
for(const b of $('Build Symbol Batches').all()){
  for(const m of (b.json.meta||[])) meta[(m.yahoo||m.ticker).toUpperCase()]=m;
}

// EDGAR ticker -> CIK. US filers only; European lines simply won't resolve.
const cik={};
try{
  const map=$('Fetch CIK Map').first().json||{};
  for(const k of Object.keys(map)){
    const v=map[k];
    if(v && v.ticker) cik[String(v.ticker).toUpperCase()]=String(v.cik_str).padStart(10,'0');
  }
}catch(e){}

const rows=[];
for(const item of $input.all()){
  const res=((item.json||{}).spark||{}).result||[];
  for(const r of res){
    const resp=(r.response||[])[0]||{}; const m=resp.meta||{};
    const sym=m.symbol||r.symbol; if(!sym) continue;
    // A TRUE one-day move is the latest price against the PREVIOUS BAR's close.
    // meta.chartPreviousClose is NOT yesterday: it is the close preceding the whole
    // requested range (verified against Yahoo - on range=5d it sits 5 sessions back),
    // so using it here silently produced a multi-day number labelled as daily.
    const q=((resp.indicators&&resp.indicators.quote)||[])[0]||{};
    const closes=(q.close||[]).filter(x=>typeof x==='number');
    const price=m.regularMarketPrice;
    if(typeof price!=='number') continue;
    let prev=null, prevIsBar=false;
    if(closes.length>=2){ prev=closes[closes.length-2]; prevIsBar=true; }
    else if(typeof m.chartPreviousClose==='number'){ prev=m.chartPreviousClose; }
    if(!(typeof prev==='number'&&prev>0)) continue;
    const pct=((price-prev)/prev)*100;
    // Timeframe must be stated, never inferred by the reader. This endpoint is
    // range=2d/interval=1d and pct is regularMarketPrice vs chartPreviousClose,
    // i.e. a ONE-DAY move: today so far against the prior session's close.
    const ts=(resp.timestamp||[]);
    const dstr=t=>{ try { return new Date(t*1000).toISOString().slice(0,10); } catch(e){ return null; } };
    const prevCloseDate = (prevIsBar && ts.length>=2) ? dstr(ts[ts.length-2]) : null;
    const cur=m.currency||'USD';
    const eur = toEur(price, cur);
    const mi = meta[String(sym).toUpperCase()] || {};
    rows.push({
      ticker: mi.ticker || sym, yahoo: sym, name: mi.name || sym,
      cik: cik[String(mi.ticker||sym).toUpperCase()] || cik[String(sym).toUpperCase()] || '',
      currency:cur, price, prev, eur,
      pct:Math.round(pct*100)/100,
      window:'1d',
      window_label: prevCloseDate ? ('1-day move, vs close on '+prevCloseDate)
                  : 'move since the previous available close (single session of data)',
      direction: pct<0?'down':'up'
    });
  }
}

const thr=ctx.threshold;
let breaches=rows.filter(r=>Math.abs(r.pct)>=thr)
                   .sort((a,b)=>Math.abs(b.pct)-Math.abs(a.pct));

// --- de-duplicate ---------------------------------------------------------
// The cron fires 3x a day. A name that is down 5% at 10:00 is still down 5% at
// 14:00 and 18:00 - without this you get three identical alerts for one event,
// each costing a SerpAPI search and a GPT-5 call. On-demand asks bypass it.
let fresh = breaches;
if (ctx.source !== 'invoke') {
  const sd = $getWorkflowStaticData('global');
  const today = new Date().toISOString().slice(0,10);
  sd.alerted = sd.alerted || {};
  for (const k of Object.keys(sd.alerted)) {
    if (sd.alerted[k].date !== today) delete sd.alerted[k];   // new day, clean slate
  }
  fresh = breaches.filter(b => {
    const seen = sd.alerted[b.ticker];
    if (!seen) return true;
    return Math.abs(b.pct) >= Math.abs(seen.pct) + 2;          // only if it got materially worse
  });
  for (const b of fresh) sd.alerted[b.ticker] = { date: today, pct: b.pct };
}
breaches = fresh;

// A symbol that returns no data used to vanish with no trace, so a broken
// ticker looked exactly like a quiet day. Report it instead.
const requested=[];
for(const b of $('Build Symbol Batches').all()) for(const m of (b.json.meta||[])) requested.push(m);
const back=new Set(rows.map(r=>String(r.yahoo).toUpperCase()));
const unresolved=requested.filter(m=>!back.has(String(m.yahoo||m.ticker).toUpperCase()))
                          .map(m=>`${m.name||m.ticker} (${m.yahoo||m.ticker})`);

if(!breaches.length){
  return [{ json:{ ...ctx, any:false, checked:rows.length, breaches:[], movers:[], unresolved, window:'1d', window_label:'1-day move, vs previous close' } }];
}
// one item per breach so the enrichment nodes run per name
return breaches.map(b=>({ json:{ ...ctx, any:true, checked:rows.length,
  breach:b, breaches, movers:rows, unresolved, window:'1d',
  window_label: b.window_label || '1-day move, vs previous close' } }));

const ctx=$('Compute Moves').first().json;
const breaches=(ctx.breaches||[]);

// EDGAR submissions + SerpAPI news are index-aligned with the breach list
const filings=$('Fetch Filings').all().map(i=>i.json);
const news=$('Fetch News').all().map(i=>i.json);

const enriched=breaches.map((b,idx)=>{
  const f=filings[idx]||{};
  const recent=(((f.filings||{}).recent)||{});
  const forms=[];
  const n=Math.min(8,(recent.form||[]).length);
  for(let i=0;i<n;i++){
    forms.push({ form:recent.form[i], date:recent.filingDate[i],
                 desc:(recent.primaryDocDescription||[])[i]||'' });
  }
  const nr=((news[idx]||{}).news_results||[]).slice(0,6).map(x=>({
    title:x.title||'', source:(x.source&&(x.source.name||x.source))||'',
    date:x.date||'', link:x.link||'', snippet:(x.snippet||'').slice(0,260)
  }));
  return { ...b, edgar_company:f.name||'', filings:forms, news:nr };
});

return [{ json:{ ...ctx, enriched } }];

const ctx=$('Aggregate Evidence').first().json;
const raw=$input.first().json.message?.content ?? $input.first().json;
const p=typeof raw==='string'?JSON.parse(raw):raw;

// keep <b>/<i>/<a href> that the analyst emits, neutralise everything else
const tg=s=>String(s||'')
  .replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')
  .replace(/&lt;(\/?(?:b|i))&gt;/g,'<$1>')
  .replace(/&lt;a href="([^"]*)"&gt;/g,'<a href="$1">')
  .replace(/&lt;\/a&gt;/g,'</a>');

let body=tg(String(p.report||''));
const MAX=3800;
if(body.length>MAX) {
  body=body.slice(0,MAX);
  // A blind slice can cut through an HTML tag, which makes Telegram reject the
  // whole send with "can't parse entities" / "unsupported start tag".
  const lastOpen=body.lastIndexOf('<');
  if(lastOpen>body.lastIndexOf('>')) body=body.slice(0,lastOpen);
  for(const t of ['b','i','a']){
    const o=(body.match(new RegExp('<'+t+'(?:\\s[^>]*)?>','g'))||[]).length;
    const c=(body.match(new RegExp('</'+t+'>','g'))||[]).length;
    for(let k=0;k<o-c;k++) body+='</'+t+'>';
  }
  body+='\n…(truncated)';
}

// A ticker that never resolved is a data problem, not a quiet market - say so
// rather than letting it look like the name simply did not move.
const un=(ctx.unresolved||[]);
if(un.length){
  body+=`\n\n<i>\u26a0\ufe0f No price data for: ${tg(un.join(', '))}. Check the ticker in the portfolio sheet.</i>`;
}

const names=(ctx.breaches||[]).map(b=>`${b.ticker} ${b.pct>0?'+':''}${b.pct}% (1d)`).join(', ');
return [{ json:{ chat_id:ctx.chat_id, language:ctx.language, source:ctx.source,
  text:body, checked:ctx.checked, breach_count:(ctx.breaches||[]).length,
  breaches:names, item_count:p.item_count||0,
  preview:body.replace(/<[^>]+>/g,'').slice(0,300) } }];

// Two entry paths: the orchestrator (on demand) and the cron.
let src='scheduled', chat='0', lang='en', thr=null;
try {
  const e=$('Entry (from Orchestrator)').first().json;
  if (e && e.action) {
    src='invoke'; chat=e.chat_id||chat; lang=e.language||'en';
    // "alert me on anything over 4%" -> honour it
    const m=String(e.text||'').match(/(\d+(?:[.,]\d+)?)\s*%/);
    if (m) thr=Math.abs(parseFloat(m[1].replace(',','.')));
  }
} catch (err) {}
return [{ json: { source:src, chat_id:chat, language:lang,
  threshold: thr || 4,          // default: flag anything moving 4%+ either way
  big_threshold: 7 } }];

